export class HomeComponent implements OnInit, AfterViewInit {
  homeData: any;
  visionItems: any[] = [];
  projetsRecents: any[] = [];
  partenaires: any[] = [];
  @ViewChildren('animSection', { read: ElementRef }) sections!: QueryList<ElementRef<HTMLElement>>;

  constructor(private contentService: ContentService, private router: Router) {}

  ngOnInit() {
    this.homeData = this.contentService.getHomeData();
    this.visionItems = this.homeData.visionItems;
    this.projetsRecents = this.homeData.projetsRecents;

    // Génération d'images placeholder via picsum.photos (seed pour stabilité)
    this.partenaires = Array.from({ length: 5 }).map((_, i) => ({
      nom: `Partenaire ${i + 1}`,
      // taille 150x50 adaptée à la classe h-16 ; utilisez seed pour obtenir images cohérentes entre reloads
      logo: this.placeholderLogo(i + 1, 150, 50)
    }));
  }

  // Retourne une URL d'image placeholder basée sur un seed pour avoir des images cohérentes
  // Retourne une URL d'image placeholder basée sur un seed pour avoir des images cohérentes
    placeholderLogo(index: number, width = 150, height = 50) {
      // ajouter un paramètre de version pour éviter certains caches et garantir des images cohérentes
      return `https://picsum.photos/seed/partner-${index}/${width}/${height}?v=${index}`;
    }
  ngAfterViewInit() {
    this.initialiserAnimations();
  }

  initialiserAnimations() {
    // Utiliser des batches et des timelines pour des transitions plus fluides et performantes
    gsap.defaults({ ease: 'power3.out' });

    // Batch pour les fade-in: apparaître par groupes avec léger stagger
    ScrollTrigger.batch('.fade-in', {
      onEnter: (batch) => {
        gsap.fromTo(batch, { opacity: 0, y: 30 }, {
          opacity: 1,
          y: 0,
          duration: 0.9,
          stagger: 0.08
        });
      },
      start: 'top 85%'
    });

    // Batch pour les éléments slide-up (cards / titres) avec un petit décalage entre eux
    ScrollTrigger.batch('.slide-up', {
      onEnter: (batch) => {
        gsap.fromTo(batch, { opacity: 0, y: 60 }, {
          opacity: 1,
          y: 0,
          duration: 1,
          stagger: 0.12
        });
      },
      start: 'top 85%'
    });

    // Parallax léger et plus fluide
    gsap.utils.toArray('.parallax').forEach((element: any) => {
      gsap.to(element, {
        y: -30,
        ease: 'none',
        scrollTrigger: {
          trigger: element,
          start: 'top 90%',
          end: 'bottom 10%',
          scrub: 0.6
        }
      });
    });

    // Découper le scroll en pourcentages et positionner la vidéo à chaque % (snap par pourcent)
    const video = document.querySelector('.hero-section video') as HTMLVideoElement;
    if (video) {
      // attendre les métadonnées pour connaître la durée
      video.addEventListener('loadedmetadata', () => {
        let lastPercent = -1;

        // Créer un ScrollTrigger qui suit la progression et met à jour la vidéo uniquement quand le pourcent change
        ScrollTrigger.create({
          trigger: '.hero-section',
          start: 'top top',
          end: 'bottom top',
          // scrub true pour que ScrollTrigger calcule progress en continu, mais on n'utilise que l'entier %
          scrub: true,
          onUpdate: (self) => {
            const percent = Math.round(self.progress * 100);
            if (percent !== lastPercent) {
              lastPercent = percent;
              const targetTime = Math.min(video.duration, (percent / 100) * video.duration);

              // Mettre à jour la position de la vidéo. On utilise requestAnimationFrame pour être sûr d'être dans un frame.
              requestAnimationFrame(() => {
                try {
                  // Définir currentTime directement pour "snap" à chaque pourcent
                  video.currentTime = targetTime;
                } catch (e) {
                  // Certains navigateurs peuvent lancer si manipulé trop souvent ; on ignore les erreurs silencieusement
                  // (ou on pourrait fallback en faisant un petit gsap.to si nécessaire)
                }
              });
            }
          }
        });
      });
    }

    // ----- Section-based animations: typewriter for text + fade-up for images -----
    // We use @ViewChildren to target all sections with the template ref `#animSection`.
    // For each textual element (h1,h2,h3,p) we split the text into <span> per character
    // then animate those characters with a stagger to achieve a typewriter-like effect.
    const splitText = (el: HTMLElement) => {
      if (!el) return;
      // don't split twice
      if ((el as any).__splitDone) return;
      const text = el.textContent || '';
      el.textContent = '';
      const frag = document.createDocumentFragment();
      for (const ch of text.split('')) {
        const span = document.createElement('span');
        span.textContent = ch === ' ' ? '\u00A0' : ch;
        span.style.display = 'inline-block';
        span.style.opacity = '0';
        span.style.transform = 'translateY(6px)';
        frag.appendChild(span);
      }
      el.appendChild(frag);
      (el as any).__splitDone = true;
    };

    const mm = gsap.matchMedia();

    // Setup animations for each section
    this.sections?.forEach((sectionRef) => {
      const sectionEl = sectionRef.nativeElement as HTMLElement;
      // find textual nodes we want to animate letter-by-letter
      const textNodes: HTMLElement[] = Array.from(sectionEl.querySelectorAll('h1,h2,h3,p')) as HTMLElement[];
      textNodes.forEach(splitText);

      const images: HTMLElement[] = Array.from(sectionEl.querySelectorAll('img')) as HTMLElement[];

      // Use matchMedia to tweak timings on mobile vs desktop for responsiveness
      mm.add({ isSmall: '(max-width: 767px)' }, (context) => {
        const isSmall = (context as any).conditions['isSmall'];
        const charStagger = isSmall ? 0.01 : 0.03; // faster stagger on small screens
        const durationPerChar = isSmall ? 0.04 : 0.06;

        // timeline triggered when section enters viewport
        const tl = gsap.timeline({
          scrollTrigger: {
            trigger: sectionEl,
            start: 'top 85%',
            end: 'bottom 15%',
            toggleActions: 'play reverse play reverse',
            // markers: true // enable for debugging
          }
        });

        // animate each textual node's characters
        textNodes.forEach((tn) => {
          const chars = Array.from(tn.querySelectorAll('span')) as HTMLElement[];
          if (chars.length === 0) return;
          tl.to(chars, {
            opacity: 1,
            y: 0,
            duration: durationPerChar * 10,
            ease: 'power2.out',
            stagger: charStagger
          }, '<');
          // small gap between different text nodes
          tl.to({}, { duration: 0.06 });
        });

        // images: fade-in + lift
        if (images.length) {
          tl.from(images, {
            opacity: 0,
            y: 30,
            duration: 0.8,
            ease: 'power2.out',
            stagger: 0.08
          }, '<');
        }

        return () => {
          // cleanup when media query is removed
        };
      });
    });
  }

  defilerVersSections() {
    gsap.to(window, {
      duration: 0.8,
      scrollTo: { y: '.vision-section', offsetY: 80 },
      ease: 'power2.out'
    });
  }

  retourHaut() {
    gsap.to(window, {
      duration: 0.8,
      scrollTo: { y: 0 },
      ease: 'power2.out'
    });
  }

  naviguerVersInvestissement() {
    this.router.navigate(['/investissement']);
  }
}
